<?php
session_start();require_once '../shared/config.php';require_once '../shared/security.php';o2oCsrfToken();requireLogin('vendor','login.php');$db=getDB();$vendorId=(int)$_SESSION['vendor_id'];$message='';$error='';
function generateReviewSummary(PDO $db,int $itemId,int $vendorId):array{
  $apiKey=getenv('OPENAI_API_KEY')?:'';$model=getenv('O2O_AI_MODEL')?:'gpt-5.6-luna';if(!$apiKey)return[false,'AI provider is not configured.'];
  $own=$db->prepare("SELECT id,name FROM items WHERE id=? AND vendor_id=?");$own->execute([$itemId,$vendorId]);if(!$own->fetch())return[false,'Item not found.'];
  $rs=$db->prepare("SELECT rating,review,created_at FROM reviews WHERE item_id=? ORDER BY created_at DESC LIMIT 100");$rs->execute([$itemId]);$reviews=$rs->fetchAll();if(!$reviews)return[false,'No customer reviews exist for this item yet.'];
  $lines=[];foreach($reviews as $r)$lines[]='Rating: '.$r['rating'].'/5 | Review: '.$r['review'];$reviewText=implode("\n",$lines);
  $payload=['model'=>$model,'input'=>[['role'=>'user','content'=>[['type'=>'input_text','text'=>'Summarize these customer reviews for a traditional-wear marketplace. Return ONLY valid JSON with keys: summary (string), positive_points (array of short strings), common_complaints (array of short strings). Do not invent facts and do not treat a single review as consensus.\n\n'.$reviewText]]]]];
  $ch=curl_init('https://api.openai.com/v1/responses');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$apiKey],CURLOPT_POSTFIELDS=>json_encode($payload),CURLOPT_TIMEOUT=>60]);$raw=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);
  if($raw===false||$http<200||$http>=300)return[false,'AI request failed (HTTP '.$http.').'];
  $resp=json_decode($raw,true);$text=$resp['output_text']??'';if(!$text&&isset($resp['output']))foreach($resp['output'] as $out)foreach(($out['content']??[]) as $part)if(isset($part['text']))$text.=$part['text'];
  $text=str_replace(["\`\`\`json","\`\`\`"],'',trim($text));$data=json_decode($text,true);if(!is_array($data)||!isset($data['summary']))return[false,'AI returned an unreadable summary.'];
  $positive=json_encode(array_values(array_map('strval',$data['positive_points']??[])),JSON_UNESCAPED_UNICODE);$complaints=json_encode(array_values(array_map('strval',$data['common_complaints']??[])),JSON_UNESCAPED_UNICODE);
  $up=$db->prepare("INSERT INTO review_summaries (item_id,summary,positive_points,common_complaints) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE summary=VALUES(summary),positive_points=VALUES(positive_points),common_complaints=VALUES(common_complaints),generated_at=CURRENT_TIMESTAMP");$up->execute([$itemId,trim((string)$data['summary']),$positive,$complaints]);return[true,'Review summary generated.'];
}
if($_SERVER['REQUEST_METHOD']==='POST'){o2oRequireCsrf();[$ok,$msg]=generateReviewSummary($db,(int)($_POST['item_id']??0),$vendorId);if($ok)$message=$msg;else$error=$msg;}
$st=$db->prepare("SELECT i.id,i.name,(SELECT COUNT(*) FROM reviews r WHERE r.item_id=i.id) review_count FROM items i WHERE i.vendor_id=? ORDER BY i.name");$st->execute([$vendorId]);$items=$st->fetchAll();
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Review Summary – O2O Tradition</title><style>
body{font-family:Arial;background:#F4F7F4;color:#1A2E1A;margin:0}.nav{background:#0F1B2D;color:#C9A84C;padding:18px 28px;display:flex;justify-content:space-between}.nav a{color:#E8CC82;text-decoration:none;margin-left:15px}.main{max-width:900px;margin:auto;padding:30px}.card{background:#fff;padding:22px;margin:15px 0;box-shadow:0 2px 10px #0001}.select{padding:10px;width:100%;border:1px solid #ddd}.button{margin-top:12px;padding:11px 16px;background:#0F1B2D;color:#C9A84C;border:0}.notice{padding:12px;background:#D1FAE5;color:#065F46}.error{padding:12px;background:#FEF2F2;color:#991B1B}</style></head><body><div class="nav"><b>O2O Tradition · AI Review Summary</b><div><a href="dashboard.php">Dashboard</a><a href="condition_ai.php">AI Condition</a><a href="logout.php">Logout</a></div></div><main class="main"><h1>AI Review Summary</h1><p style="color:#666">Generate a concise summary from actual customer reviews. No summary is generated when there are no reviews.</p><?php if($message):?><div class="notice"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><div class="card"><form method="POST"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($_SESSION['csrf_token']) ?>"><label>Item</label><select class="select" name="item_id" required><?php foreach($items as $i):?><option value="<?=$i['id']?>"><?=htmlspecialchars($i['name'])?> · <?=$i['review_count']?> review(s)</option><?php endforeach;?></select><button class="button">Generate / Refresh Summary</button></form></div></main></body></html>